def choose_move(observation):
    wx = observation['grid_width']
    hy = observation['grid_height']
    px, py = observation['self_position']
    opponent_x, opponent_y = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    remaining = observation['remaining_resource_count']
    scores = observation['scores']
    self_path = observation['self_path']
    opponent_path = observation['opponent_path']
    # Determine target: pick nearest resource if any
    if resources:
        target = min(resources, key=lambda r: abs(r[0]-px)+abs(r[1]-py))
        tx, ty = target
    else:
        # No resources, target opponent to block or chase
        tx, ty = opponent_x, opponent_y
    dx = dy = 0
    if tx > px:
        dx = 1
    elif tx < px:
        dx = -1
    if ty > py:
        dy = 1
    elif ty < py:
        dy = -1
    # Prioritize horizontal move if not blocked
    for move in [(dx,0),(0,dy)]:
        nx, ny = px+move[0], py+move[1]
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            return list(move)
    # If desired moves blocked, try moving without conflicting with obstacle
    for move in [(0,1),(0,-1),(1,0),(-1,0)]:
        nx, ny = px+move[0], py+move[1]
        if 0 <= nx < wx and 0 <= ny < hy and (nx, ny) not in obstacles:
            return list(move)
    return [0, 0]
